#!/bin/sh
# Builds the page as static files — no server needed to hear a poem:
#
#   index.html, assets/  the page (web/, built by Vite), sending its requests to the compiler beside it
#                        and playing through the Prosody player (no Strudel runtime: docs/player.md)
#   speech-worker.mjs    the worker the reading's neural voices run in (web/public)
#   site.json            the page's data: option lists, presets, mappings (`prosody-web --site`)
#   prosody.js           the compiler's bindings, generated by `wasm-bindgen`
#   prosody_bg.wasm      the whole compiler (`crates/prosody-wasm`)
#   synth.js             the Prosody player's synth bindings, loaded by its render worker
#   synth_bg.wasm        the synth (`crates/prosody-synth-wasm`, docs/player.md §5), both written
#                        into web/public by scripts/build-synth.sh and so carried by the page's build
#   readings/            the recorded readings of the example poems (examples/readings, made by
#                        scripts/readings/render.mjs): a manifest and an MP3 a line and voice
#   notices.json         every package the site and the apps ship, with its licence texts
#                        (scripts/notices.mjs), for the page's Licences dialog
#
#   ./scripts/build-site.sh              into target/site
#   ./scripts/build-site.sh DIR          into DIR
#
# PROSODY_NEURAL_VOICES=off builds the page without the reading's neural voices (Kokoro, Piper,
# Kitten): speech-worker.mjs is left out and the page offers only the recorded readings and the
# browser's voice. Those engines carry eSpeak NG (GPL-3) and fetch their code at run time, which an
# App Store app may not; the iOS app is built this way (`mise run site:ios`). Unset, or `on`, every
# engine is there, as the web page and the Android app have them.
#
# Serve the directory with any static file server (`python3 -m http.server -d target/site`);
# opening index.html from disk does not work, because browsers refuse to fetch beside a file://.
set -eu

here=$(dirname "$0")
cd "$here/.."
dir="${1:-target/site}"
neural="${PROSODY_NEURAL_VOICES:-on}"
case "$neural" in
  on | off) ;;
  *) echo "build-site: PROSODY_NEURAL_VOICES is '$neural' — 'on' or 'off'" >&2; exit 1 ;;
esac

# The C parser's objects are wasm, and macOS's `ar` cannot index them — the link then fails with
# every `ts_*` symbol undefined. The toolchain's own `llvm-ar` can (rust-toolchain.toml asks for
# `llvm-tools`).
host=$(rustc -vV | sed -n 's/^host: //p')
llvm_ar="$(rustc --print sysroot)/lib/rustlib/$host/bin/llvm-ar"
if [ ! -x "$llvm_ar" ]; then
  echo "build-site: no llvm-ar at $llvm_ar — rustup component add llvm-tools" >&2
  exit 1
fi

AR_wasm32_unknown_unknown="$llvm_ar" \
  cargo build --release --locked -p prosody-wasm --target wasm32-unknown-unknown
# The synth goes in web/public, so the page's own build carries it, as the served page's does.
./scripts/build-synth.sh

# The page, from its lockfile. Node comes from mise (mise.toml) or the PATH.
npm --prefix web ci --no-audit --no-fund --loglevel=error
VITE_PROSODY_NEURAL_VOICES="$neural" npm --prefix web run --silent build >/dev/null
mkdir -p "$dir"
# Each of the page's files and folders replaces its older copy rather than merging into it: hashed
# names and removed files must not linger beside the new ones. The app ships this directory
# (src-tauri), so a lingering file is shipped too — an older build's drums/ held drum machines
# with no licence.
for entry in web/dist/*; do
  rm -rf "${dir:?}/${entry#web/dist/}"
done
# What older builds wrote and this one does not: Strudel's runtime, its globals and its import map's
# target, before the Prosody player replaced it. Left in place, the app would ship them.
rm -rf "${dir:?}/vendor" "${dir:?}/strudel-globals.mjs"
cp -R web/dist/. "$dir/"
if [ "$neural" = off ]; then
  # The page offers no neural engine (VITE_PROSODY_NEURAL_VOICES), so nothing asks for their worker.
  rm -f "$dir/speech-worker.mjs"
  echo "build-site: without the neural voices (PROSODY_NEURAL_VOICES=off): no speech-worker.mjs in $dir"
fi
cargo run --quiet --release --locked -p prosody-web -- --site "$dir"
# What the site and the apps ship, and the licence of each, for the page's Licences dialog.
node scripts/notices.mjs "$dir"

target_dir=$(cargo metadata --format-version 1 --no-deps |
  grep -o '"target_directory":"[^"]*"' | cut -d'"' -f4)

# The bindings' generator, exactly the version of the `wasm-bindgen` crate in Cargo.lock.
bindgen=$(./scripts/wasm-bindgen.sh)
rm -f "$dir/prosody.wasm" # the name before the bindings were generated
"$bindgen" --target web --no-typescript --out-name prosody --out-dir "$dir" \
  "$target_dir/wasm32-unknown-unknown/release/prosody_wasm.wasm"
echo "build-site: $(wc -c < "$dir/prosody_bg.wasm" | tr -d ' ') bytes of prosody_bg.wasm in $dir"
test -f "$dir/synth_bg.wasm" # carried from web/public by the page's build

# The recordings, copied whole (a stale copy of a removed recording must not linger). Without them
# the page still works: the recorded engine says it has none and a live engine reads.
rm -rf "$dir/readings"
if [ -f examples/readings/manifest.json ]; then
  cp -R examples/readings "$dir/readings"
  echo "build-site: $(find "$dir/readings" -name '*.mp3' | wc -l | tr -d ' ') recorded lines, $(du -sk "$dir/readings" | cut -f1) kB, in $dir/readings"
else
  echo "build-site: no examples/readings/manifest.json — the site has no recorded readings" >&2
fi
